/**
 * Friendly aliases over the generated OpenAPI schema.
 *
 * `schema.d.ts` is regenerated by `npm run gen:api` and must not be edited by
 * hand. Everything else in the app imports from here instead of reaching into
 * `components["schemas"][...]` directly, so a rename on the backend surfaces as
 * one broken line in this file rather than fifty across the app.
 */
import type { components } from './schema'

type Schemas = components['schemas']

export type Author = Schemas['AuthorRead']
export type Cookbook = Schemas['CookbookRead']
export type Ingredient = Schemas['IngredientRead']
export type Measurement = Schemas['MeasurementRead']
export type Preparation = Schemas['PreparationRead']

export type Recipe = Schemas['RecipeRead']
export type RecipeCreate = Schemas['RecipeCreate']
export type RecipeUpdate = Schemas['RecipeUpdate']

export type Step = Schemas['StepRead']
export type StepCreate = Schemas['StepCreate']
export type Requirement = Schemas['RequirementRead']
export type RequirementCreate = Schemas['RequirementCreate']

export type RecipeIngredient = Schemas['RecipeIngredientRead']
export type RecipeIngredientCreate = Schemas['RecipeIngredientCreate']
export type RecipeIngredientUpdate = Schemas['RecipeIngredientUpdate']

/** The lookup tables share a shape: an id and a unique name. */
export type Lookup = { id: number; name: string }
